package com.example.library.controller;
import com.example.library.model.Book;import com.example.library.repo.BookRepository;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.client.RestTemplate;
@RestController @RequestMapping("/api/chat") public class ChatController {private final BookRepository books;@Value("${GEMINI_API_KEY:}") private String apiKey;public ChatController(BookRepository b){books=b;}
 @PostMapping public Map<String,String> chat(@RequestBody Map<String,String> body){String question=body.getOrDefault("message","").trim();if(question.isBlank())return Map.of("answer","Please enter a question.");String q=question.toLowerCase();List<Book> all=books.findAll();List<Book> matches=all.stream().filter(b->(b.getTitle()+" "+b.getAuthor()+" "+b.getCategory()).toLowerCase().contains(q)||Arrays.stream(q.split("\\s+")).filter(w->w.length()>3).anyMatch(w->(b.getTitle()+" "+b.getAuthor()+" "+b.getCategory()).toLowerCase().contains(w))).limit(5).toList();String context=matches.isEmpty()?"No matching books were found in the current catalogue.":matches.stream().map(b->b.getTitle()+" by "+b.getAuthor()+" (category: "+b.getCategory()+", available: "+b.getAvailableQuantity()+")").reduce((a,b)->a+"; "+b).orElse("");
 if(!apiKey.isBlank()){try{String url="https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key="+apiKey;Map<String,Object> request=Map.of("contents",List.of(Map.of("parts",List.of(Map.of("text","Answer the user's library question using this retrieved catalogue context. If the context does not answer it, say so. Context: "+context+"\nQuestion: "+question)))));HttpHeaders headers=new HttpHeaders();headers.setContentType(MediaType.APPLICATION_JSON);Map<?,?> response=new RestTemplate().postForObject(url,new HttpEntity<>(request,headers),Map.class);var candidates=(List<Map<String,Object>>)response.get("candidates");var content=(Map<String,Object>)candidates.get(0).get("content");var parts=(List<Map<String,Object>>)content.get("parts");return Map.of("answer",String.valueOf(parts.get(0).get("text")));}catch(Exception ignored){}}
 return Map.of("answer","Library catalogue results: "+context+". You can ask about a title, author, or category. For natural-language answers, configure GEMINI_API_KEY on the backend.");}
}
